    const object = document.toJSON();
    if (!object || !object.kind) continue;
    if (options.source === "envoy" && object.kind === "CustomResourceDefinition"
      && String(object.metadata && object.metadata.name || "").endsWith(".gateway.networking.k8s.io")) {
